using UnityEngine;using System.Linq;using System.Text;
public static class ProbeRoadDirections{public static string Main(){var sb=new StringBuilder();var terrain=Terrain.activeTerrains[0];foreach(float z in new[]{90f,93f,96f,99f})for(float x=30;x<=75;x+=3){var p=new Vector3(x,0,z);p.y=terrain.SampleHeight(p)+terrain.transform.position.y+.02f;var hits=Physics.BoxCastAll(p+Vector3.up*1.243f,new Vector3(1.034f,1.034f,2.101f),Vector3.right,Quaternion.Euler(0,90,0),.225f,~0,QueryTriggerInteraction.Ignore);var hit=hits.FirstOrDefault(h=>h.normal.y<=.65f);if(hit.collider!=null)sb.AppendLine(p+" -> "+hit.collider.name+" "+hit.distance+" "+hit.normal);}return sb.ToString();}}
